 i:[[4,"stk","æg"],[300,"g","sukker"],[1,"tsk","vaniljesukker"],[250,"g","hvedemel"],[2,"tsk","bagepulver"],[2,"dl","mælk"],[50,"g","smør"],[200,"g","smør (til topping)"],[250,"g","brun farin (til topping)"],[150,"g","kokosmel (til topping)"],[1,"dl","mælk (til topping)"]],
